const PRAYERS=[['Fajr','Aube','✦'],['Sunrise','Lever du soleil','◌'],['Dhuhr','Midi','☀'],['Asr','Après-midi','◒'],['Maghrib','Coucher du soleil','◉'],['Isha','Nuit','☾']];
const METHODS={mwl:{fajr:18,isha:17},uoif:{fajr:12,isha:12},isna:{fajr:15,isha:15},egypt:{fajr:19.5,isha:17.5},makkah:{fajr:18.5,ishaMinutes:90}};
const NAMES={Fajr:'Fajr',Sunrise:'Chourouq',Dhuhr:'Dhuhr',Asr:'Asr',Maghrib:'Maghrib',Isha:'Isha'};
const state={lat:null,lon:null,timezone:Intl.DateTimeFormat().resolvedOptions().timeZone,label:'',times:{},next:null,notified:{},method:localStorage.getItem('nour-method')||'mwl',pushKey:null,pushReady:false};
const $=selector=>document.querySelector(selector);const rad=x=>x*Math.PI/180;const deg=x=>x*180/Math.PI;
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),3200)}
function getCityDate(date=new Date()){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:state.timezone,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(date);const get=t=>+parts.find(p=>p.type===t).value;return{year:get('year'),month:get('month'),day:get('day')}}
function addDays(parts,count){const d=new Date(Date.UTC(parts.year,parts.month-1,parts.day+count));return{year:d.getUTCFullYear(),month:d.getUTCMonth()+1,day:d.getUTCDate()}}
function timezoneOffsetMinutes(date,timeZone){const parts=new Intl.DateTimeFormat('en-US',{timeZone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(date);const get=t=>+parts.find(p=>p.type===t).value;return(Date.UTC(get('year'),get('month')-1,get('day'),get('hour'),get('minute'),get('second'))-date.getTime())/60000}
function dateAtMinutes(parts,minutes,timeZone){const base=Date.UTC(parts.year,parts.month-1,parts.day);let guess=new Date(base+minutes*60000);let offset=timezoneOffsetMinutes(guess,timeZone);let result=new Date(base+minutes*60000-offset*60000);const refined=timezoneOffsetMinutes(result,timeZone);if(refined!==offset)result=new Date(base+minutes*60000-refined*60000);return result}
function solar(parts,lat,lon,timeZone){const start=Date.UTC(parts.year,0,0),day=Math.floor((Date.UTC(parts.year,parts.month-1,parts.day)-start)/86400000);const gamma=2*Math.PI/365*(day-1);const eq=229.18*(.000075+.001868*Math.cos(gamma)-.032077*Math.sin(gamma)-.014615*Math.cos(2*gamma)-.040849*Math.sin(2*gamma));const dec=.006918-.399912*Math.cos(gamma)+.070257*Math.sin(gamma)-.006758*Math.cos(2*gamma)+.000907*Math.sin(2*gamma)-.002697*Math.cos(3*gamma)+.00148*Math.sin(3*gamma);const noonGuess=new Date(Date.UTC(parts.year,parts.month-1,parts.day,12));const tz=timezoneOffsetMinutes(noonGuess,timeZone)/60;const noon=720-4*lon-eq+60*tz;const hourAngle=alt=>{const v=(Math.sin(rad(alt))-Math.sin(rad(lat))*Math.sin(dec))/(Math.cos(rad(lat))*Math.cos(dec));return Math.abs(v)>1?null:deg(Math.acos(v))*4};return{noon,dec,hourAngle}}
function compute(parts,lat,lon,timeZone,methodKey){const m=METHODS[methodKey],s=solar(parts,lat,lon,timeZone),rise=s.hourAngle(-.833),fajr=s.hourAngle(-m.fajr),isha=m.isha?s.hourAngle(-m.isha):null;const asrAltitude=deg(Math.atan(1/(1+Math.tan(Math.abs(rad(lat)-s.dec)))));const asr=s.hourAngle(asrAltitude);const sunrise=rise==null?s.noon-360:s.noon-rise,sunset=rise==null?s.noon+360:s.noon+rise;return{Fajr:dateAtMinutes(parts,fajr==null?sunrise-90:s.noon-fajr,timeZone),Sunrise:dateAtMinutes(parts,sunrise,timeZone),Dhuhr:dateAtMinutes(parts,s.noon+2,timeZone),Asr:dateAtMinutes(parts,asr==null?s.noon+240:s.noon+asr,timeZone),Maghrib:dateAtMinutes(parts,sunset,timeZone),Isha:dateAtMinutes(parts,m.ishaMinutes?sunset+m.ishaMinutes:isha==null?sunset+90:s.noon+isha,timeZone)}}
function formatTime(date){return new Intl.DateTimeFormat('fr-FR',{timeZone:state.timezone,hour:'2-digit',minute:'2-digit'}).format(date)}
function renderDates(){const now=new Date();$('#gregorianDate').textContent=new Intl.DateTimeFormat('fr-FR',{timeZone:state.timezone,weekday:'long',day:'numeric',month:'long'}).format(now);try{$('#hijriDate').textContent=new Intl.DateTimeFormat('fr-FR-u-ca-islamic',{timeZone:state.timezone,day:'numeric',month:'long',year:'numeric'}).format(now)}catch{}}
function render(){if(state.lat==null)return;const now=new Date(),today=getCityDate(now);state.times=compute(today,state.lat,state.lon,state.timezone,state.method);let next=Object.entries(state.times).find(([key,date])=>key!=='Sunrise'&&date>now);if(!next){const tomorrow=addDays(today,1);next=['Fajr',compute(tomorrow,state.lat,state.lon,state.timezone,state.method).Fajr]}state.next=next;$('#nextPrayer').textContent=NAMES[next[0]];$('#nextTime').textContent='à '+formatTime(next[1]);const list=$('#prayerList');list.replaceChildren(...PRAYERS.map(([key,sub,symbol])=>{const row=document.createElement('div');row.className='prayer'+(key===next[0]&&next[1].toLocaleDateString('en',{timeZone:state.timezone})===now.toLocaleDateString('en',{timeZone:state.timezone})?' active':'');const symbolEl=document.createElement('div');symbolEl.className='symbol';symbolEl.textContent=symbol;const copy=document.createElement('div');const name=document.createElement('div');name.className='name';name.textContent=NAMES[key];const subEl=document.createElement('div');subEl.className='sub';subEl.textContent=sub;copy.append(name,subEl);const time=document.createElement('time');time.textContent=formatTime(state.times[key]);row.append(symbolEl,copy,time);return row}));renderDates();tick()}
function tick(){if(!state.next)return;const ms=state.next[1]-new Date();if(ms<=0){checkLocalNotifications();render();return}const h=Math.floor(ms/36e5),m=Math.floor(ms%36e5/6e4),s=Math.floor(ms%6e4/1000);$('#countdown').textContent=`dans ${h?String(h).padStart(2,'0')+' h ':''}${String(m).padStart(2,'0')} min ${String(s).padStart(2,'0')} s`}
async function sendNotification(title,options){try{if('serviceWorker'in navigator){const registration=await navigator.serviceWorker.ready;return registration.showNotification(title,options)}return new Notification(title,options)}catch{toast('Le navigateur bloque ce type de notification.')}}
function checkLocalNotifications(){if(!('Notification'in window)||Notification.permission!=='granted'||!state.times)return;const now=new Date();for(const[key,time]of Object.entries(state.times)){if(key==='Sunrise')continue;const id=key+'-'+time.toISOString().slice(0,10);if(Math.abs(now-time)<65000&&!state.notified[id]){state.notified[id]=true;sendNotification(`Il est l’heure de prier ${NAMES[key]}`,{body:`La prière de ${NAMES[key]} commence maintenant.`,icon:'./icon.svg',tag:id,data:{url:'./'}})}}}
function saveLocation(location){localStorage.setItem('nour-location',JSON.stringify(location))}
function setLocation(location,{save=true}={}){state.lat=Number(location.lat);state.lon=Number(location.lon);state.timezone=location.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone;state.label=location.label||'Position actuelle';if(save)saveLocation({lat:state.lat,lon:state.lon,timezone:state.timezone,label:state.label,source:location.source||'manual'});$('#locationText').textContent=state.label;$('#locationButton').classList.remove('loading');render();refreshPushSchedule()}
function setMode(mode){document.querySelectorAll('.mode-tab').forEach(button=>button.classList.toggle('active',button.dataset.mode===mode));$('#manualLocation').classList.toggle('hidden',mode!=='manual');$('#liveLocation').classList.toggle('hidden',mode!=='live')}
function openLocation(){setMode('manual');$('#locationDialog').showModal();$('#city').focus()}
async function useLiveLocation(){if(!navigator.geolocation){toast('La géolocalisation n’est pas disponible.');return}$('#liveLocationButton').disabled=true;$('#liveLocationButton').textContent='Localisation en cours…';navigator.geolocation.getCurrentPosition(position=>{setLocation({lat:position.coords.latitude,lon:position.coords.longitude,timezone:Intl.DateTimeFormat().resolvedOptions().timeZone,label:'Position actuelle',source:'device'});$('#locationDialog').close();toast('Position enregistrée uniquement sur cet appareil.');$('#liveLocationButton').disabled=false;$('#liveLocationButton').textContent='Utiliser ma position actuelle'},()=>{toast('Localisation refusée ou indisponible.');$('#liveLocationButton').disabled=false;$('#liveLocationButton').textContent='Utiliser ma position actuelle'},{enableHighAccuracy:false,timeout:9000,maximumAge:3600000})}
async function searchCity(event){event.preventDefault();const city=$('#city').value.trim(),country=$('#country').value.trim();if(city.length<2||country.length<2){toast('Indiquez une ville et un pays.');return}const status=$('#searchStatus'),results=$('#searchResults');status.textContent='Recherche…';results.replaceChildren();try{const params=new URLSearchParams({name:`${city}, ${country}`,count:'6',language:'fr',format:'json'});const response=await fetch(`https://geocoding-api.open-meteo.com/v1/search?${params}`,{referrerPolicy:'no-referrer'});if(!response.ok)throw new Error('search');const data=await response.json();const places=(data.results||[]).filter(item=>item.latitude!=null&&item.longitude!=null&&item.timezone);status.textContent=places.length?'Sélectionnez la bonne ville :':'Aucune ville trouvée. Vérifiez l’orthographe.';for(const place of places){const button=document.createElement('button');button.type='button';button.className='search-result';const strong=document.createElement('strong');strong.textContent=place.name;const detail=document.createElement('span');detail.textContent=[place.admin1,place.country].filter(Boolean).join(', ');button.append(strong,detail);button.addEventListener('click',()=>{setLocation({lat:place.latitude,lon:place.longitude,timezone:place.timezone,label:`${place.name}, ${place.country}`,source:'city'});$('#locationDialog').close();toast('Ville enregistrée sur cet appareil.')});results.append(button)}}catch{status.textContent='Recherche indisponible. Réessayez plus tard.'}}
function isIOS(){return/iPad|iPhone|iPod/.test(navigator.userAgent)&&!window.MSStream}function isStandalone(){return window.matchMedia('(display-mode: standalone)').matches||window.navigator.standalone===true}
function urlBase64ToUint8Array(base64){const padding='='.repeat((4-base64.length%4)%4),raw=atob((base64+padding).replace(/-/g,'+').replace(/_/g,'/'));return Uint8Array.from([...raw].map(char=>char.charCodeAt(0)))}
async function loadPushConfig(){if(!('serviceWorker'in navigator)||!('PushManager'in window))return;try{const response=await fetch('/.netlify/functions/push-config',{headers:{accept:'application/json'}});if(!response.ok)return;const data=await response.json();if(data.publicKey){state.pushKey=data.publicKey;state.pushReady=true}}catch{}}
function buildSchedule(days=31){const today=getCityDate();const schedule=[];for(let i=0;i<days;i++){const date=addDays(today,i),times=compute(date,state.lat,state.lon,state.timezone,state.method);for(const[key,time]of Object.entries(times)){if(key!=='Sunrise'&&time>Date.now())schedule.push({at:time.toISOString(),prayer:NAMES[key]})}}return schedule}
async function syncPushSchedule(subscription){if(!subscription||state.lat==null)return false;const response=await fetch('/.netlify/functions/subscribe',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({subscription:subscription.toJSON(),schedule:buildSchedule()})});return response.ok}
async function refreshPushSchedule(){if(!state.pushReady||!('serviceWorker'in navigator)||state.lat==null)return;try{const registration=await navigator.serviceWorker.ready,subscription=await registration.pushManager.getSubscription();if(subscription)await syncPushSchedule(subscription)}catch{}}
async function enableNotifications(){if(!('Notification'in window)){toast('Notifications non prises en charge sur cet appareil.');return}if(isIOS()&&!isStandalone()){$('#installDialog').showModal();return}try{const permission=await Notification.requestPermission();if(permission!=='granted'){toast('Autorisation refusée dans les réglages du navigateur.');return}const registration=await navigator.serviceWorker.ready;if(state.pushReady){let subscription=await registration.pushManager.getSubscription();if(!subscription)subscription=await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:urlBase64ToUint8Array(state.pushKey)});const synced=await syncPushSchedule(subscription);if(synced){localStorage.setItem('nour-notifications','push');updateNotify('push');await sendNotification('Rappels activés',{body:'Nour peut maintenant vous prévenir même lorsque l’app est fermée.',icon:'./icon.svg',tag:'nour-enabled'});return}}localStorage.setItem('nour-notifications','local');updateNotify('local');await sendNotification('Rappels activés',{body:'Gardez Nour ouvert pour recevoir les rappels sur cette version.',icon:'./icon.svg',tag:'nour-enabled'});toast('Rappels actifs lorsque le site est ouvert. Le push Netlify doit encore être configuré.')}catch{toast('Impossible d’activer les rappels pour le moment.')}}
function updateNotify(mode=localStorage.getItem('nour-notifications')){const active='Notification'in window&&Notification.permission==='granted';$('#notifyButton').classList.toggle('enabled',active);$('#notifyButtonText').textContent=active?(mode==='push'?'Rappels hors ligne activés':'Rappels activés'):'Activer les rappels'}
function loadSavedLocation(){try{const saved=JSON.parse(localStorage.getItem('nour-location')||'null');if(saved&&Number.isFinite(saved.lat)&&Number.isFinite(saved.lon)){setLocation(saved,{save:false});return}}catch{}setLocation({lat:47.5596,lon:7.5886,timezone:'Europe/Zurich',label:'Bâle (par défaut)',source:'default'},{save:false})}
function init(){
  $('#method').value=state.method;$('#method').addEventListener('change',event=>{state.method=event.target.value;localStorage.setItem('nour-method',state.method);render();refreshPushSchedule();toast('Horaires recalculés.')});
  $('#notifyButton').addEventListener('click',enableNotifications);$('#locationButton').addEventListener('click',openLocation);$('#settingsButton').addEventListener('click',openLocation);$('#cancelLocation').addEventListener('click',()=>$('#locationDialog').close('cancel'));$('#closePrivacy').addEventListener('click',()=>$('#privacyDialog').close());$('#closeInstall').addEventListener('click',()=>$('#installDialog').close());$('#privacyButton').addEventListener('click',()=>$('#privacyDialog').showModal());$('#citySearchForm').addEventListener('submit',searchCity);$('#liveLocationButton').addEventListener('click',useLiveLocation);document.querySelectorAll('.mode-tab').forEach(button=>button.addEventListener('click',()=>setMode(button.dataset.mode)));
  if('serviceWorker'in navigator)navigator.serviceWorker.register('./service-worker.js').catch(()=>{});setInterval(()=>{tick();checkLocalNotifications()},1000);document.addEventListener('visibilitychange',()=>{if(!document.hidden){render();checkLocalNotifications()}});loadSavedLocation();loadPushConfig();updateNotify();
}
init();
